// Import fs and path modules here
const fs = require('fs');
const path = require('path');

// Create the loadSecrets function here
function loadSecrets() {
  // Use path.join to create the file path here
  const secretsPath = path.join(__dirname, 'secrets.env');
  // Use fs.existsSync to check if the secrets file exists and store the result in a variable
  const fileExists = fs.existsSync(secretsPath);
  // Add if statement to throw error if file doesn't exist
  if (!fileExists) {
    throw new Error('Secrets file not found');
  }
  // Use fs.readFileSync to read the secrets file content as a UTF-8 string and store it in a variable
  const fileContent = fs.readFileSync(secretsPath, 'utf-8');
  // Split the file content by newline characters here
  const lines = fileContent.split('\n');
  // Parse each line into key-value pairs here
  lines.forEach(line => {
    const [key, value] = line.split('=');
    if (key && value) {
      // Iterate through parsed pairs and set as environment variables
      process.env[key.trim()] = value.trim();
    }
  });
}

